action.command:
cd /workspace && cat > boot.mjs <<'EOF'
import { JSDOM } from 'jsdom';
import fs from 'fs';
const html = fs.readFileSync('/workspace/dist/basic/index.html','utf8');
const dom = new JSDOM(html, {url:'http://localhost:8099/basic/index.html', pretendToBeVisual:true});
const w = dom.window;
for (const k of ['window','document','navigator','HTMLElement','Node','customElements','MutationObserver','CustomEvent','Event','getComputedStyle','requestAnimationFrame','cancelAnimationFrame','DOMParser','XMLHttpRequest','CSS','history','location','screen','localStorage','sessionStorage','matchMedia','ResizeObserver','IntersectionObserver','fetch','Blob','URL','Image','HTMLCanvasElement']) {
  try { globalThis[k] = (k in w) ? w[k] : globalThis[k]; } catch {}
}
globalThis.requestAnimationFrame = (cb)=>setTimeout(()=>cb(Date.now()),0);
globalThis.cancelAnimationFrame = (id)=>clearTimeout(id);
const bundle = fs.readFileSync('/workspace/dist/mastercode/3_26_1_410dc25_git_last_commit_at_2026-09-23__10-05-39/js/masterportal.js','utf8');
try {
  await import('data:text/javascript;base64,'+Buffer.from(bundle).toString('base64'));
  console.log('MODULE_IMPORTED_OK');
} catch(e){ console.log('IMPORT_ERR:', e.constructor.name, String(e.message).slice(0,300)); }
await new Promise(r=>setTimeout(r,3000));
console.log('__appMounted =', w.__appMounted);
console.log('root children:', w.document.getElementById('masterportal-root')?.children.length);
EOF
timeout 160 node boot.mjs 2>&1 | tail -25; rm -f boot.mjs

